type GameStat = {match:string;players:Record<string,Array<[string,Array<[string,number]>]>>};
const MATCH_STATS_KEYS=['apr18','may03','may17','jun14','jun28','jul11','jul25','aug09','sep19','oct04'];
const normalizePlayerName=(v:string)=>v.toLowerCase().replace(/ё/g,'е').replace(/[^а-яa-z]/g,'');
function PlayerGameDetails({player,gameStats}:{player:string;gameStats:GameStat[]}){
 const found=gameStats.flatMap((g,i)=>{const entry=Object.entries(g.players).find(([name])=>normalizePlayerName(name)===normalizePlayerName(player));return entry?[{i,sections:entry[1],tab:g.match}]:[]});
 if(!gameStats.length)return <Text style={styles.muted}>Поматчевая статистика 2026 загружается. Проверь подключение к интернету.</Text>;
 if(!found.length)return <Text style={styles.muted}>В загруженных протоколах матчей 2026 года индивидуальные показатели этого игрока не найдены. Это не означает, что он не участвовал в играх.</Text>;
 return <View style={{gap:12}}>{found.map((g)=>{const game=SEASON_2026.find(m=>m.id===MATCH_STATS_KEYS[g.i]);return <View key={g.i} style={{padding:12,borderWidth:1,borderColor:'#57452C',backgroundColor:'#171612',gap:8}}><Text style={styles.sectionLabel}>{game?game.date+' · '+game.home+' '+game.homeScore+':'+game.awayScore+' '+game.away:g.tab}</Text>{g.sections.map(([section,fields],j)=><View key={j} style={{gap:3}}><Text style={styles.gold}>{section.toUpperCase()}</Text><Text style={styles.body}>{fields.map(([label,value])=>label+': '+value).join(' · ')}</Text></View>)}<Text style={styles.muted}>Источник: лист «{g.tab}» таблицы «Статистика Чемпионат России 2026»</Text></View>})}</View>;
}
function PlayerPortrait({photo,number}:{photo?:string;number:string}){
 const [failed,setFailed]=useState(false);
 useEffect(()=>setFailed(false),[photo]);
 return photo&&!failed?<Image source={{uri:BRAND_ASSETS+'../player-photos/'+photo}} onError={()=>setFailed(true)} resizeMode="cover" style={{width:64,height:76}}/>:<Text style={{color:GOLD,fontSize:26,fontWeight:'700'}}>#{number}</Text>;
}
