 const [readConfirmed,setReadConfirmed]=useState(false);
 const [playerDetails,setPlayerDetails]=useState({fullName:'',age:'',weight:'',height:'',position:''});
 const [benchmarks,setBenchmarks]=useState({jump:'',forty:'',cones:''});
 const [attendance,setAttendance]=useState<string[]>([]);
 const [trainingDate,setTrainingDate]=useState('');
 const [onboardingDone,setOnboardingDone]=useState(false);
 const [onboardingError,setOnboardingError]=useState('');
 const [playerUnit,setPlayerUnit]=useState<'offense'|'defense'|'special'|null>(null);
